/* Pixel Snake Game Styles */
:root {
  --color-bg: #1a1a2e;
  --color-card: #16213e;
  --color-primary: #0f3460;
  --color-accent: #e94560;
  --color-text: #eaeaea;
  --color-snake: #4ecca3;
  --color-food: #e94560;
  --color-grid: #0a0a1a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--color-card);
  border-radius: 16px;
  padding: 24px;
  max-width: 500px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-accent);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--color-snake);
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--color-grid);
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(10, 10, 26, 0.92);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  text-align: center;
  transition: opacity 0.3s ease;
}

.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}

.overlay-content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--color-accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  color: var(--color-text);
  max-width: 280px;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  background: var(--color-primary);
  color: var(--color-text);
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, border-color 0.2s;
  min-width: 100px;
}

.btn:hover {
  background: var(--color-accent);
}

.btn:focus-visible {
  outline: 3px solid var(--color-snake);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.btn.primary {
  background: var(--color-accent);
}

.btn.primary:hover {
  background: var(--color-snake);
  color: var(--color-bg);
}

.instructions {
  text-align: center;
  font-size: 0.9rem;
  color: #888;
  line-height: 1.4;
}

@media (max-width: 400px) {
  .game-container {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 80px;
  }
}

(function() {
  'use strict';

  // Constants
  const GRID_SIZE = 20;
  const CELL_SIZE = 20;
  const CANVAS_SIZE = GRID_SIZE * CELL_SIZE;
  const INITIAL_SPEED = 150;

  // DOM elements
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlayTitle');
  const overlayText = document.getElementById('overlayText');
  const overlayButton = document.getElementById('overlayButton');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  // Game state
  let snake = [];
  let direction = { x: 1, y: 0 };
  let nextDirection = { x: 1, y: 0 };
  let food = { x: 5, y: 5 };
  let score = 0;
  let gameState = 'paused'; // 'playing', 'paused', 'gameover'
  let gameLoop = null;
  let speed = INITIAL_SPEED;

  // Initialize snake
  function initSnake() {
    snake = [
      { x: 10, y: 10 },
      { x: 9, y: 10 },
      { x: 8, y: 10 }
    ];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
  }

  // Place food at random empty cell
  function placeFood() {
    const empty = [];
    for (let x = 0; x < GRID_SIZE; x++) {
      for (let y = 0; y < GRID_SIZE; y++) {
        if (!snake.some(s => s.x === x && s.y === y)) {
          empty.push({ x, y });
        }
      }
    }
    if (empty.length > 0) {
      food = empty[Math.floor(Math.random() * empty.length)];
    }
  }

  // Draw everything
  function draw() {
    // Clear
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);

    // Draw grid lines (subtle)
    ctx.strokeStyle = '#1a1a2e';
    ctx.lineWidth = 1;
    for (let i = 0; i <= GRID_SIZE; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL_SIZE, 0);
      ctx.lineTo(i * CELL_SIZE, CANVAS_SIZE);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL_SIZE);
      ctx.lineTo(CANVAS_SIZE, i * CELL_SIZE);
      ctx.stroke();
    }

    // Draw snake
    snake.forEach((segment, index) => {
      ctx.fillStyle = index === 0 ? '#4ecca3' : '#3aa88a';
      ctx.fillRect(
        segment.x * CELL_SIZE + 1,
        segment.y * CELL_SIZE + 1,
        CELL_SIZE - 2,
        CELL_SIZE - 2
      );
    });

    // Draw food
    ctx.fillStyle = '#e94560';
    ctx.beginPath();
    ctx.arc(
      food.x * CELL_SIZE + CELL_SIZE / 2,
      food.y * CELL_SIZE + CELL_SIZE / 2,
      CELL_SIZE / 2 - 2,
      0,
      Math.PI * 2
    );
    ctx.fill();
  }

  // Update game state
  function update() {
    if (gameState !== 'playing') return;

    // Apply next direction
    direction = { ...nextDirection };

    // Calculate new head
    const head = snake[0];
    const newHead = {
      x: head.x + direction.x,
      y: head.y + direction.y
    };

    // Check wall collision
    if (newHead.x < 0 || newHead.x >= GRID_SIZE || newHead.y < 0 || newHead.y >= GRID_SIZE) {
      gameOver();
      return;
    }

    // Check self collision
    if (snake.some(s => s.x === newHead.x && s.y === newHead.y)) {
      gameOver();
      return;
    }

    // Move snake
    snake.unshift(newHead);

    // Check food
    if (newHead.x === food.x && newHead.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      placeFood();
      // Speed up slightly
      if (speed > 60) speed -= 5;
      restartLoop();
    } else {
      snake.pop();
    }

    draw();
  }

  // Game over
  function gameOver() {
    gameState = 'gameover';
    clearInterval(gameLoop);
    gameLoop = null;
    overlayTitle.textContent = 'Game Over';
    overlayText.textContent = `Your score: ${score}. Press Restart to play again.`;
    overlayButton.textContent = 'Restart';
    overlay.classList.remove('hidden');
  }

  // Restart loop with current speed
  function restartLoop() {
    if (gameLoop) clearInterval(gameLoop);
    gameLoop = setInterval(update, speed);
  }

  // Start / resume game
  function startGame() {
    if (gameState === 'gameover') {
      resetGame();
    }
    gameState = 'playing';
    overlay.classList.add('hidden');
    pauseBtn.textContent = 'Pause';
    restartLoop();
  }

  // Pause game
  function pauseGame() {
    if (gameState !== 'playing') return;
    gameState = 'paused';
    clearInterval(gameLoop);
    gameLoop = null;
    overlayTitle.textContent = 'Paused';
    overlayText.textContent = 'Press Space or click Resume to continue.';
    overlayButton.textContent = 'Resume';
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Resume';
  }

  // Reset game
  function resetGame() {
    clearInterval(gameLoop);
    gameLoop = null;
    score = 0;
    scoreEl.textContent = '0';
    speed = INITIAL_SPEED;
    initSnake();
    placeFood();
    gameState = 'paused';
    overlayTitle.textContent = 'How to Play';
    overlayText.textContent = 'Use arrow keys to move. Press Space to pause/resume. Click Start Game to begin.';
    overlayButton.textContent = 'Start Game';
    overlay.classList.remove('hidden');
    pauseBtn.textContent = 'Pause';
    draw();
  }

  // Toggle pause/resume
  function togglePause() {
    if (gameState === 'playing') {
      pauseGame();
    } else if (gameState === 'paused' || gameState === 'gameover') {
      startGame();
    }
  }

  // Keyboard handler
  function handleKey(e) {
    const key = e.key;
    if (key === ' ' || key === 'Spacebar') {
      e.preventDefault();
      togglePause();
      return;
    }
    if (gameState !== 'playing') return;

    let newDir = null;
    switch (key) {
      case 'ArrowUp':
        if (direction.y !== 1) newDir = { x: 0, y: -1 };
        break;
      case 'ArrowDown':
        if (direction.y !== -1) newDir = { x: 0, y: 1 };
        break;
      case 'ArrowLeft':
        if (direction.x !== 1) newDir = { x: -1, y: 0 };
        break;
      case 'ArrowRight':
        if (direction.x !== -1) newDir = { x: 1, y: 0 };
        break;
      default:
        return;
    }
    if (newDir) {
      e.preventDefault();
      nextDirection = newDir;
    }
  }

  // Event listeners
  document.addEventListener('keydown', handleKey);
  overlayButton.addEventListener('click', startGame);
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', function() {
    resetGame();
  });

  // Initialize
  initSnake();
  placeFood();
  draw();
  overlay.classList.remove('hidden');
})();
